    if num_slots != 9 or len(masses) != 9:
        raise ValueError("Input must be for a 9-slot rotor with 9 distinct masses.")

    total_mass = sum(masses)
    target_mass_per_group = total_mass // 3

    if total_mass % 3 != 0:
        raise ValueError("Total mass of blades must be divisible by 3.")

    groups = []
    for i in range(3):
        group_masses = sorted([masses[j] for j in range(3) if (j + i * 3) % 9 == 0])
        if sum(group_masses) != target_mass_per_group:
            raise ValueError("Each group must have equal mass.")
        groups.append(group_masses)

    arrangements = 0
    for group1 in itertools.permutations(groups[0]):
        for group2 in itertools.permutations(groups[1]):
            for group3 in itertools.permutations(groups[2]):
                slots_used = set()
                for i, group in enumerate(groups):
                    for j, mass in enumerate(group):
                        while True:
                            slot = (i * 3 + j) % num_slots
                            if slot not in slots_used:
                                slots_used.add(slot)
                                break
                arrangements += 1

    return arrangements



