def count_rotor_arrangements(num_slots: int, masses: list[int]) -> int:
    if num_slots != 9 or len(masses) != 9:
        raise ValueError("Invalid input: num_slots must be 9 and masses must have length 9")

    def is_valid_arrangement(arrangement: list[int]) -> bool:
        for i in range(3):
            group1 = arrangement[i * 3:(i * 3) + 3]
            group2 = arrangement[(i * 3) + 3:(i * 3) + 6]
            group3 = arrangement[(i * 3) + 6:(i * 3) + 9]
            if sum(group1) != sum(group2) or sum(group2) != sum(group3):
                return False
        return True

    def generate_arrangements(index: int, arrangement: list[int]) -> None:
        if index == num_slots:
            if is_valid_arrangement(arrangement):
                yield arrangement
            return

        for i in range(num_slots):
            arrangement[index] = masses[i]
            generate_arrangements(index + 1, arrangement.copy())

    count = 0
    for arrangement in generate_arrangements(0, [None] * num_slots):
        count += 1
    return count



