def calculate_p_scaled(num_slots: int, num_books: int, scaling_factor: int) -> int:
    """Calculates the scaled probability of a specific book distribution on bookshelves."""
    total_arrangements = factorial(num_slots) // (factorial(num_slots - num_books) * factorial(num_books))

    valid_arrangements = 0
    for i in range(num_slots):
        if i + 2 <= num_slots:
            valid_arrangements += count_valid_arrangements(i, num_books, num_slots)

    return round((valid_arrangements / total_arrangements) * scaling_factor, 0)


def count_valid_arrangements(start_index: int, num_books: int, num_slots: int) -> int:
    """Counts valid arrangements starting at a specific index."""
    if num_books == 0:
        return 1

    count = 0
    for i in range(start_index, num_slots - num_books + 1):
        if i + 2 <= num_slots and is_valid_arrangement(i, num_books, num_slots):
            count += count_valid_arrangements(i + 3, num_books - 1, num_slots)

    return count


def is_valid_arrangement(start_index: int, num_books: int, num_slots: int) -> bool:
    """Checks if a given arrangement is valid."""
    if start_index + 2 >= num_slots:
        return False
    for i in range(start_index, start_index + 3):
        if i < num_slots and i != start_index + 1:
            return True
    return False


def factorial(n: int) -> int:
    """Calculates the factorial of a number."""
    if n == 0:
        return 1
    return n * factorial(n - 1)



