def is_valid_number(num: str) -> bool:
    """Check if a number satisfies the given conditions."""
    for i in range(len(num) - 1):
        if int(num[i]) > int(num[i + 1]) + 1 or (int(num[i + 1]) < int(num[i]) + 7 and int(num[i + 2]) >= int(num[i + 1])):
            return False
    return True


def calculate_inverse_prob(min_num: int, max_num: int) -> Optional[int]:
    """Calculate the probability 'a' that a number is of the form a1a2a3a4a5 such that 
    a1 ≤ a2 + 1 ≤ a3 - 7 < a4 ≤ a5 + 2 and return its inverse."""

