import itertools
import math

def count_rotor_arrangements(n: int, masses: List[int]) -> int:
    def is_valid_group(masses: List[int], group: List[int]) -> bool:
        return sum(group) % 3 == 0 and len(set(group)) == 3

    def get_equilateral_triangles(slots: List[int]) -> List[List[int]]:
        triangles = []
        for i in range(n):
            triangle = [slots[(i + j) % n] for j in (1, 2)]
            triangles.append(triangle)
        return triangles

    def is_valid_arrangement(masses: List[int], slots: List[int]) -> bool:
        groups = get_equilateral_triangles(slots)
        for group in groups:
            if not is_valid_group(masses, [masses[slot - 1] for slot in group]):
                return False
        return True

    def count_arrangements(masses: List[int], slots: List[int]) -> int:
        if is_valid_arrangement(masses, slots):
            return 1
        else:
            return 0

    total = 0
    for p in itertools.permutations(masses):
        total += count_arrangements(p, list(range(1, n + 1)))

    # Account for rotations and reflections
    total /= math.factorial(n)
    total *= 2  # Reflections

    return int(total)

