def solve_min_distance(mx: float, my: float) -> float:
    """
    Calculate the minimum distance between a point (mx, my) and the curve g(x) = (x + 1)/(x - 2)

    Args:
        mx (float): The x-coordinate of the point.
        my (float): The y-coordinate of the point.

    Returns:
        float: The minimum distance in meters, rounded to two decimal places.
    """

    # Define the function g(x) = (x + 1)/(x - 2)
    def g(x: float) -> float:
        if x > 2:
            return (x + 1) / (x - 2)
        else:
            raise ValueError("g(x) is not defined for x <= 2")

    # Define the function to calculate the distance between a point and the curve
    def distance(mx: float, my: float, x: float) -> float:
        return math.sqrt((mx - x)**2 + (my - g(x))**2)

    # Find the minimum distance using numerical methods
    from scipy.optimize import minimize_scalar

    res = minimize_scalar(lambda x: distance(mx, my, x), bracket=[2.0001, 100])
    min_distance = res.fun * 10  # Convert to meters and round to two decimal places

    return round(min_distance, 2)

