        dp = [[[0] * 4 for _ in range(4)] for _ in range(3)]

        # Base case: There is one way to choose and place triangles when there are no colors or numbers left
        for i in range(3):
            for j in range(4):
                if not colors[i][1]:
                    dp[i][j][0] = 1

        # Dynamic programming
        for color, count in colors:
            for num, cnt in numbers:
                for i in range(3):
                    for j in range(4):
                        if dp[i][j][color - 1]:
                            for k in range(4):
