def min_cost(distances: List[List[int]]) -> int:
    n = len(distances)
    dp = [[float('inf')] * n for _ in range(n)]

    # Base case: no more cities to visit
    for i in range(n):
        dp[i][i] = 0

    for k in range(1, n):
        for i in range(n):
            for j in range(n):
                if i == j:
