def calculate_final_value(total_triangles: int) -> float:
    if total_triangles < 0:
        return 0.0
    elif total_triangles == 0:
        return 16.0

    # memoization table to store the number of valid arrangements for each total_triangles value
    arrangements: Dict[int, int] = {0: 16, total_triangles: 0}

    def dfs(remaining_triangles: int, current_color: int, current_number: int) -> None:
        if remaining_triangles == 0:
            arrangements[total_triangles] += 1
            return

