               (count_one == sum(slots_with_one_book)) and \
               (len(slots_with_two_books) == count_two)

    def backtrack(index: int, books_placed: int):
        if books_placed > k or index >= n:
            return

        if books_placed == k and is_valid(slots[:index]):
            return 1

        result = 0
        for i in range(min(books_placed + 2, max_books_per_slot), -1, -1):
            if index > 0 and slots[index - 1] == -1:
                slots[index - 1] = i
                result += backtrack(index + 1, books_placed + i)
                slots[index - 1] = -1

            if index < len(slots_with_one_book) and slots_with_one_book[index] > 0:
