def maximize_profit(c0: float, c1: float, c2: float, c3: float, a_p: float, a_q: float) -> int | None:
    A = -3 * c3
    B = -2 * (c2 + a_q)
    C = a_p - c1
    discriminant = B * B - 4 * A * C
    if discriminant < 0:
        return None
    sqrt_disc = sqrt(discriminant)
    if A != 0:
        x1 = (-B + sqrt_disc) / (2 * A)
        x2 = (-B - sqrt_disc) / (2 * A)
        x = max(x1, x2)
    else:
        if B == 0:
            return None
        x = -C / B
    if x <= 0:
        return None
    return int(round(x))

