def calculate_probability_score(n: int, options: int, correct_score: int, penalty: int, target: int) -> float:
    """Calculate 100 * probability that a random guess yields exactly `target` points."""
    if options <= 0:
        raise ValueError("options must be positive")
    if correct_score == penalty:
        # All questions give same score, probability is 1 if target matches that score, else 0
        if target == correct_score * n:
            return 100.0
        return 0.0

    # Score formula: score = correct_score * X + penalty * (n - X)
    # => target = penalty * n + (correct_score - penalty) * X
    diff = correct_score - penalty
    if diff == 0:
        # Already handled above, but keep safe
        if target == penalty * n:
            return 100.0
        return 0.0

    if (target - penalty * n) % diff != 0:
        return 0.0

    X = (target - penalty * n) // diff
    if X < 0 or X > n:
        return 0.0

    prob = math.comb(n, X) * ((1 / options) ** X) * ((options - 1) / options) ** (n - X)
    return round(100 * prob, 2)
