def solve_gps_problem(A: Tuple[float, float, float],
                      B: Tuple[float, float, float],
                      C: Tuple[float, float, float],
                      D: Tuple[float, float, float]) -> float:
    Ax, Ay, Az = A
    Bx, By, Bz = B
    Cx, Cy, Cz = C
    Dx, Dy, Dz = D

    ABx = Bx - Ax
    ABy = By - Ay
    ABz = Bz - Az

    def M(t: float) -> Tuple[float, float, float]:
        return (Ax + t * ABx, Ay + t * ABy, Az + t * ABz)

    def D_minus_M(t: float) -> Tuple[float, float, float]:
        return (Dx - M(t)[0], Dy - M(t)[1], Dz - M(t)[2])

    def cross(u: Tuple[float, float, float],
              v: Tuple[float, float, float]) -> Tuple[float, float, float]:
        return (u[1] * v[2] - u[2] * v[1],
                u[2] * v[0] - u[0] * v[2],
                u[0] * v[1] - u[1] * v[0])

