def calculate_p_scaled(slots: int, books: int, multiplier: int) -> float:
    # total number of ways to distribute identical books into distinct slots
    total = math.comb(books + slots - 1, slots - 1)
    if total == 0:
        return 0.0

    count = 0
    # each slot can have 0, 1, or 2 books
    for assignment in product([0, 1, 2], repeat=slots):
