def _count_favorable(slots: int, books: int) -> int:
    """Count assignments of `books` identical books into `slots` where each slot holds 0‑2 books,
    exactly 4 or 6 slots contain exactly one book, and any slot with two books has empty neighbours."""
    if books < 0 or books > 2 * slots:
        return 0

    total = math.comb(books + slots - 1, slots - 1)  # stars‑and‑bars

    favorable = 0

    def rec(idx: int, remaining: int, current: list[int]) -> None:
        nonlocal favorable
        if idx == slots:
            if remaining == 0:
                n1 = sum(1 for v in current if v == 1)
                if n1 not in (4, 6):
                    return
                # check isolation of 2‑book slots
                for i, v in enumerate(current):
                    if v == 2:
                        if i > 0 and current[i - 1] != 0:
                            return
                        if i < slots - 1 and current[i + 1] != 0:
                            return
                favorable += 1
            return

        for v in (0, 1, 2):
            if v <= remaining:
                rec(idx + 1, remaining - v, current + [v])

