import itertools
from math import comb
from typing import List


def _primes_up_to(n: int) -> List[int]:
    """Return a list of all prime numbers ≤ n."""
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for p in range(2, int(n ** 0.5) + 1):
        if sieve[p]:
            for multiple in range(p * p, n + 1, p):
                sieve[multiple] = False
    return [i for i, is_prime in enumerate(sieve) if is_prime]


def calculate_probability(n: int, k: int) -> float:
    """
    Calculate the probability (as a percentage rounded to one decimal place)
    that among k tickets drawn without replacement from 1..n:
      - at least two are prime numbers, and
      - the sum of the k numbers is even.
    """
    if not (1 <= k <= n):
        raise ValueError("k must satisfy 1 ≤ k ≤ n")
    if n < 2:
        return 0.0  # no primes possible

    primes = _primes_up_to(n)
    prime_set = set(primes)

    total_combinations = comb(n, k)
    valid = 0

    for combo in itertools.combinations(range(1, n + 1), k):
        prime_count = sum(1 for x in combo if x in prime_set)
        if prime_count < 2:
            continue
        if sum(combo) % 2 == 0:
            valid += 1

    probability = (valid / total_combinations) * 100.0
    return round(probability, 1)


