import math

def find_min_first_payment(total_debt: float, target_percent: float, months: int, decay_ratio: float) -> int:
    if months <= 0:
        raise ValueError("months must be a positive integer")
    if decay_ratio <= 0:
        raise ValueError("decay_ratio must be positive")
    if not (0 <= target_percent <= 1):
        raise ValueError("target_percent must be between 0 and 1 inclusive")

    target = total_debt * target_percent
    if target <= 0:
        return 0

    if math.isclose(decay_ratio, 1.0, rel_tol=1e-12):
        sum_factor = months
    else:
        sum_factor = (1 - decay_ratio ** months) / (1 - decay_ratio)

    if sum_factor <= 0:
        raise ValueError("sum_factor must be positive")

    m = math.ceil(target / sum_factor)
    return int(m)
