def calculate_probability(
    type1_cases: int = 2,
    type2_cases: int = 1,
    type1_expired: int = 5,
    type2_expired: int = 3,
) -> float:
    from math import comb

    def total_cases() -> int:
        return type1_cases + type2_cases

    def expired_cases_in_case(case_type: str) -> int:
        if case_type == "type1":
            return type1_expired
        elif case_type == "type2":
            return type2_expired
        else:
            raise ValueError("Invalid case type")

    def total_expired() -> int:
        return (type1_cases * type1_expired) + (type2_cases * type2_expired)

    def favorable_outcomes(case_type: str) -> int:
        expired_in_case = expired_cases_in_case(case_type)
        non_expired_in_case = 24 - expired_in_case
        # Choose 2 expired and 8 non-expired from the case
        return comb(expired_in_case, 2) * comb(non_expired_in_case, 8)

    total_outcomes = 0

    for case_type in ["type1", "type2"]:
        total_outcomes += favorable_outcomes(case_type)

    probability_type1_given_2_expired = (
        favorable_outcomes("type1") / total_outcomes
    )

    return round(probability_type1_given_2_expired, 2)

