def calculate_yields(num_wells: int, initial_yield: int, decrease_per_well: int) -> Tuple[int, int]:
    if num_wells < 0 or initial_yield < 0 or decrease_per_well <= 0:
        raise ValueError("All inputs must be non-negative with a positive decrease per well.")

    wells = list(range(num_wells + 1))
    yields = [initial_yield - i * decrease_per_well for i in range(len(wells))]

    return tuple(zip(wells, yields))

def maximize_oil_production(initial_wells: int, initial_yield: int, decrease_per_well: int) -> int:
    if initial_wells < 0 or initial_yield < 0 or decrease_per_well <= 0:
        raise ValueError("All inputs must be non-negative with a positive decrease per well.")

    total_yields = calculate_yields(initial_wells, initial_yield, decrease_per_well)

    max_production = -1
    optimal_additional_wells = -1

    for additional_wells, yield_per_well in total_yields:
        daily_production = (initial_wells + additional_wells) * yield_per_well
        if daily_production > max_production:
            max_production = daily_production
            optimal_additional_wells = additional_wells

