def max_charity_revenue(milk_tea_limit: int, cake_limit: int, menu1_price: int, menu1_milk_tea: int, menu1_cake: int, menu2_price: int, menu2_milk_tea: int, menu2_cake: int) -> int:
    def solve(milk_tea_left: int, cake_left: int) -> int:
        if milk_tea_left < 0 or cake_left < 0:
            return float('-inf')
        if milk_tea_left == 0 and cake_left == 0:
            return 0
        sell_menu1 = menu1_price + solve(milk_tea_left - menu1_milk_tea, cake_left - menu1_cake)
