def is_arithmetic_progression(a: int, b: int, c: int) -> bool:
    """
    Check if three numbers form an arithmetic progression.
    """
    return (b - a) == (c - b)

def count_ap_triplets(n: int, max_sum: int) -> int:
    """
    Count the number of ways to choose 3 cards from n such that their numbers
    form an arithmetic progression and their sum does not exceed max_sum.
    """
    count = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            k = (2 * j) - i
            if k > n:
                break
            if is_arithmetic_progression(i, j, k) and i + j + k <= max_sum:
                count += 1
    return count

