def count_grid_ways(numbers: List[int]) -> int:
    from itertools import combinations, permutations

    def valid_combination(comb):
        row_sums = [sum(comb[:3]), sum(comb[3:5]), comb[5]]
        return len(set(row_sums)) == 1

    total_numbers = len(numbers)
    if total_numbers < 6 or (total_numbers - 6) % 2 != 0:
        return 0

    valid_combinations = []

    for comb in combinations(numbers, 6):
        if valid_combination(comb):
            valid_combinations.append(comb)

    count = 0
    for perm in permutations(valid_combinations[0]):
        if all(p in c for p, c in zip(perm, valid_combinations)):
            count += 1

    return count // (3 * 2 * 1)  # Account for overcounting due to permutations

