                green_pomelo_capital_per_ha * green_pomelo_area + king_orange_capital_per_ha * king_orange_area <= max_capital)

    def calculate_profit(green_pomelo_area: int, king_orange_area: int) -> int:
        return (green_pomelo_area * profit_green_pomelo + king_orange_area * profit_king_orange)

