def binomial_coefficient(n: int, k: int) -> int:
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1

    C = [0] * (k + 1)
    C[0] = 1

    for i in range(1, n + 1):
        j = min(i, k)
        while j > 0:
            C[j] += C[j - 1]
            j -= 1

    return C[k]

