from math import factorial

def is_valid_coloring(coloring: List[int]) -> bool:
    for i in range(8):
        for j in range(i + 1, 8):
            if abs(i - j) % 4 == 2 or abs(i - j) % 4 == 3:
                if coloring[i] // 4 == coloring[j] // 4:
                    return False
            else:
                if coloring[i] % 4 == coloring[j] % 4:
                    return False
    return True

def calculate_final_value(n: int) -> float:
    # There are 3 colors and 4 triangles per color, so we have 12 triangles in total.
    # We need to find the number of valid colorings where adjacent faces (sharing an edge)
    # have different colors and vertices (sharing only a vertex) have different numbers.

    # The problem can be solved using graph coloring techniques with backtracking.
    from itertools import permutations

    def backtrack(index: int, used_colors: List[int]) -> int:
        if index == 8:
            return 1
        count = 0
        for color in range(3):
            if not (used_colors[2 * index] & (1 << color) or used_colors[2 * index + 1] & (1 << color)):
                used_colors[2 * index] |= 1 << color
                used_colors[2 * index + 1] |= 1 << color
                count += backtrack(index + 1, used_colors)
                used_colors[2 * index] &= ~(1 << color)
                used_colors[2 * index + 1] &= ~(1 << color)
        return count

    valid_colorings = 0
    for perm in permutations(range(12)):
        if is_valid_coloring([perm[i] // 4 for i in range(8)]):
            valid_colorings += 1

    # The number of ways to choose and place the triangles.
    N = valid_colorings * factorial(3) ** 4
    return (N // 8 + 16)

