from math import factorial

def calculate_final_value(n: int) -> float:
    if n != 1152 and n != 0:
        raise ValueError("Input must be either 1152 or 0")

    # Precomputed values for derangements of 4 items
    d4 = 9

    def derangement(n):
        if n == 0: return 1
        if n == 1: return 0
        return (n - 1) * (derangement(n - 1) + derangement(n - 2))

    # Number of ways to color the octahedron's faces such that adjacent faces have different colors
    def count_colorings():
        # There are 3! = 6 ways to assign 3 colors to 3 pairs of opposite faces.
        # For each assignment, there are d4 derangements for the remaining two faces.
        return 6 * (d4 ** 2)

    # Number of ways to number the faces such that adjacent faces have different numbers
    def count_numberings():
        # There are 4! = 24 ways to assign numbers to one pair of opposite faces.
        # For each assignment, there are d4 derangements for the remaining two pairs.
        return (factorial(4) ** 3)

    total_ways = count_colorings() * count_numberings()

    if n == 1152:
        return total_ways / 8 + 16.0
    elif n == 0:
        return 16.0

