def prime_factors(n: int) -> Dict[int, int]:
    """Return prime factorization of n as dict {prime: exponent}."""
    factors: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2  # after 2, check odd numbers
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def carmichael_lambda(n: int) -> int:
    """Compute Carmichael function λ(n) for n >= 1."""
    if n == 1:
        return 1
    factors = prime_factors(n)
    lambdas: List[int] = []
    for p, k in factors.items():
        if p == 2:
            if k == 1:
                lambdas.append(1)
            elif k == 2:
                lambdas.append(2)
            else:
                lambdas.append(2 ** (k - 2))
        else:
            lambdas.append(p ** (k - 1) * (p - 1))
    # compute lcm of all lambdas
    result = 1
    for lam in lambdas:
        result = result * lam // math.gcd(result, lam)
    return result

